 "content": "def transform(grid):
    """Fill zero cells lying horizontally between same-colored markers."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != 0]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
